   177  struct CFF2TopDictOpSet : TopDictOpSet<>
   178  {
   179    static inline void process_op (OpCode op, NumInterpEnv& env, CFF2TopDictValues& dictval)
   180    {
   181      switch (op) {
   182        case OpCode_FontMatrix:
   183          {
   184            DictVal val;
   185            val.init ();
   186            dictval.add_op (op, env.substr);
   187            env.clear_args ();
   188          }
   189          break;
   190
   191        case OpCode_vstore:
   192          dictval.vstoreOffset = env.argStack.pop_uint ();
   193          env.clear_args ();
   194          break;
   195        case OpCode_FDSelect:
   196          dictval.FDSelectOffset = env.argStack.pop_uint ();
   197          env.clear_args ();
   198          break;
   199
   200        default:
   201          SUPER::process_op (op, env, dictval);
   202          /* Record this operand below if stack is empty, otherwise done */
   203          if (!env.argStack.is_empty ()) return;
   204      }
   205
   206      if (unlikely (env.in_error ())) return;
   207
   208      dictval.add_op (op, env.substr);
   209    }
   210
   211    typedef TopDictOpSet<> SUPER;
   212  };
